  desc = {
    ["prac_concentration_basic"] = "Practice emptying your mind and focusing on a specific thought, avoiding distractions.",
    ["prac_concentration_intermediate"] = "Practice maintaining your focus on a specific thought or image even when uncomfortable or distracted.",
    ["prac_psionics_advan"] = "Focus on your inner metal strength, making it easy to call forth your psionic gifts.",
    ["prac_psionics_begin"] = "Practice calming and emptying your mind, thinking thoughts as they come and then allowing them to flow through you and onward.",
    ["prac_psionics_inter"] = "Clear your mind even in the midst of discomfort, maintaining your calm and poise.",
    ["prac_psionics_prof_basic"] = "Practice focusing your powers through a crystalline medium.",
    ["prac_psionics_prof_ritual"] = "Practice holding mental images and scenes in your mind for an extended period without your mind wandering.",
    ["practice_biokin_adrenaline"] = "Contemplate your powers and improve your ability to trigger a burst of adrenaline on command.\n\nPower Difficulty: 4\n\nCurrent Power Level: <u_spell_level:biokin_adrenaline>",
    ["practice_biokin_adrenaline_knack"] = "Contemplate your powers and improve your ability to trigger a burst of adrenaline on command.\n\nPower Difficulty: 2\n\nCurrent Power Level: <u_spell_level:biokin_adrenaline_knack>",
    ["practice_biokin_armor_skin"] = "Contemplate your powers and improve your ability to harden your flesh against incoming damage.\n\nPower Difficulty: 4\n\nCurrent Power Level: <u_spell_level:biokin_armor_skin>",
    ["practice_biokin_breathe_skin"] = "Contemplate your powers and improve your ability to draw any possible oxygen from the environment.\n\nPower Difficulty: 2\n\nCurrent Power Level: <u_spell_level:biokin_breathe_skin>",
    ["practice_biokin_climate_control"] = "Contemplate your powers and improve your ability to withstand temperature variations.\n\nPower Difficulty: 4\n\nCurrent Power Level: <u_spell_level:biokin_climate_control>",
    ["practice_biokin_combat_dance"] = "Contemplate your powers and improve your overall combat prowess.\n\nPower Difficulty: 8\n\nCurrent Power Level: <u_spell_level:biokin_combat_dance>",
    ["practice_biokin_dash"] = "Contemplate your powers and improve your ability to cross distances in moments.\n\nPower Difficulty: 3\n\nCurrent Power Level: <u_spell_level:biokin_dash>",
    ["practice_biokin_enhance_mobility"] = "Contemplate your powers and improve your ability to deal with encumbering gear.\n\nPower Difficulty: 5\n\nCurrent Power Level: <u_spell_level:biokin_enhance_mobility>",
    ["practice_biokin_flexibility"] = "Contemplate your powers and improve your ability to move your body.\n\nPower Difficulty: 3\n\nCurrent Power Level: <u_spell_level:biokin_flexibility>",
    ["practice_biokin_flexibility_knack"] = "Contemplate your powers and improve your ability to move your body.\n\nPower Difficulty: 2\n\nCurrent Power Level: <u_spell_level:biokin_flexibility_knack>",
    ["practice_biokin_guided_evolution"] = "Contemplate your powers and improve your ability to alter how mutations are expressed.\n\nPower Difficulty: 9\n\nCurrent Power Level: <u_spell_level:biokin_guided_evolution>",
    ["practice_biokin_hammerhand"] = "Contemplate your powers and improve your ability to eschew the use of tools, using your own body in place of a hammer or wrench.\n\nPower Difficulty: 5\n\nCurrent Power Level: <u_spell_level:biokin_hammerhand>",
    ["practice_biokin_hurricane_blows"] = "Contemplate your powers and improve your ability to strike your opponents faster than thought.\n\nPower Difficulty: 10\n\nCurrent Power Level: <u_spell_level:biokin_hurricane_blows>",
    ["practice_biokin_metabolism_enhance"] = "Contemplate your powers and improve your ability to extract every possible nutrient from your food and water.\n\nPower Difficulty: 7\n\nCurrent Power Level: <u_spell_level:biokin_metabolism_enhance>",
    ["practice_biokin_overcome_pain"] = "Contemplate your powers and improve your ability to resist pain.\n\nPower Difficulty: 1\n\nCurrent Power Level: <u_spell_level:biokin_overcome_pain>",
    ["practice_biokin_perfected_motion"] = "Contemplate your powers and improve your ability to outrun a racehorse.\n\nPower Difficulty: 9\n\nCurrent Power Level: <u_spell_level:biokin_perfected_motion>",
    ["practice_biokin_physical_enhance"] = "Contemplate your powers and improve your ability to enhance your physical strength and agility.\n\nPower Difficulty: 2\n\nCurrent Power Level: <u_spell_level:biokin_physical_enhance>",
    ["practice_biokin_reflex_enhance"] = "Contemplate your powers and improve your ability to enhance your reflexes.\n\nPower Difficulty: 6\n\nCurrent Power Level: <u_spell_level:biokin_reflex_enhance>",
    ["practice_biokin_sealed_system"] = "Contemplate your powers and improve your ability to hermetically seal your body.\n\nPower Difficulty: 7\n\nCurrent Power Level: <u_spell_level:biokin_sealed_system>",
    ["practice_biokin_vitaminosis"] = "Contemplate your powers and improve your ability to convert calories into vitamins.\n\nPower Difficulty: 8\n\nCurrent Power Level: <u_spell_level:biokin_vitaminosis>",
    ["practice_clair_astral_projection"] = "Contemplate your powers and improve your ability to cast your spirit forth from your body.\n\nPower Difficulty: 8\n\nCurrent Power Level: <u_spell_level:clair_astral_projection>",
    ["practice_clair_astral_projection_knack"] = "Contemplate your powers and improve your ability to cast your spirit forth from your body.\n\nPower Difficulty: 4\n\nCurrent Power Level: <u_spell_level:clair_astral_projection_knack>",
    ["practice_clair_aura_sight"] = "Contemplate your powers and improve your ability to see others' emotional states.\n\nPower Difficulty: 3\n\nCurrent Power Level: <u_spell_level:clair_see_auras>",
    ["practice_clair_better_senses"] = "Contemplate your powers and improve your ability to enhance your mundane senses.\n\nPower Difficulty: 1\n\nCurrent Power Level: <u_spell_level:clair_better_senses>",
    ["practice_clair_better_senses_knack"] = "Contemplate your powers and improve your ability to enhance your mundane senses.\n\nPower Difficulty: 1\n\nCurrent Power Level: <u_spell_level:clair_better_senses_knack>",
    ["practice_clair_clear_sight"] = "Contemplate your powers and improve your ability to remove all barriers from your senses.\n\nPower Difficulty: 8\n\nCurrent Power Level: <u_spell_level:clair_clear_sight>",
    ["practice_clair_craft_bonus"] = "Contemplate your powers and improve your ability to determine exactly how you should build that thing you're working on.\n\nPower Difficulty: 6\n\nCurrent Power Level: <u_spell_level:clair_craft_bonus>",
    ["practice_clair_danger_sense"] = "Contemplate your powers and improve your sense of nearby danger.\n\nPower Difficulty: 2\n\nCurrent Power Level: <u_spell_level:clair_danger_sense>",
    ["practice_clair_danger_sense_knack"] = "Contemplate your powers and improve your sense of nearby danger.\n\nPower Difficulty: 1\n\nCurrent Power Level: <u_spell_level:clair_danger_sense_knack>",
    ["practice_clair_dodge_power"] = "Contemplate your powers and improve your ability to see into the very near-term future.\n\nPower Difficulty: 6\n\nCurrent Power Level: <u_spell_level:clair_dodge_power>",
    ["practice_clair_examine_item"] = "Contemplate your powers and improve your ability to determine hidden aspects of items.\n\nPower Difficulty: 4\n\nCurrent Power Level: <u_spell_level:clair_examine_item>",
    ["practice_clair_examine_item_knack"] = "Contemplate your powers and improve your ability to determine hidden aspects of items.\n\nPower Difficulty: 2\n\nCurrent Power Level: <u_spell_level:clair_examine_item_knack>",
    ["practice_clair_group_tactics"] = "Contemplate your powers and improve your ability to use foresight to advise your allies.\n\nPower Difficulty: 9\n\nCurrent Power Level: <u_spell_level:clair_group_tactics>",
    ["practice_clair_night_vision"] = "Contemplate your powers and improve your ability to sense your surroundings in the dark.\n\nPower Difficulty: 3\n\nCurrent Power Level: <u_spell_level:clair_night_vision>",
    ["practice_clair_omniscience"] = "Contemplate your powers and improve your ability to see everything.  <color_red>EVERYTHING</color>.\n\nPower Difficulty: 10\n\nCurrent Power Level: <u_spell_level:clair_omniscience>",
    ["practice_clair_perfect_shot"] = "Contemplate your powers and improve your ability to only need one shot.\n\nPower Difficulty: 7\n\nCurrent Power Level: <u_spell_level:clair_perfect_shot>",
    ["practice_clair_ranged_enhance"] = "Contemplate your powers and improve your ability to aim ranged weapons with precision.\n\nPower Difficulty: 4\n\nCurrent Power Level: <u_spell_level:clair_ranged_enhance>",
    ["practice_clair_see_map"] = "Contemplate your powers and improve your ability to extend your senses over a vast distance.\n\nPower Difficulty: 7\n\nCurrent Power Level: <u_spell_level:clair_see_map>",
    ["practice_clair_sense_hostile_creatures"] = "Contemplate your powers and improve your ability to determine nearby creatures' hostility even if you can't see them with your physical senses.\n\nPower Difficulty: 5\n\nCurrent Power Level: <u_spell_level:clair_sense_hostile_creatures>",
    ["practice_clair_sense_rads"] = "Contemplate your powers and improve your ability to detect radiation.\n\nPower Difficulty: 3\n\nCurrent Power Level: <u_spell_level:clair_sense_rads>",
    ["practice_clair_speed_reading"] = "Contemplate your powers and improve your ability to comprehend books.\n\nPower Difficulty: 2\n\nCurrent Power Level: <u_spell_level:clair_speed_reading>",
    ["practice_clair_spot_weakness"] = "Contemplate your powers and improve your sense of the vulnerabilities of your enemies.\n\nPower Difficulty: 3\n\nCurrent Power Level: <u_spell_level:clair_spot_weakness>",
    ["practice_clair_voyance"] = "Contemplate your powers and improve your ability to extend your senses beyond your body.\n\nPower Difficulty: 5\n\nCurrent Power Level: <u_spell_level:clair_voyance>",
    ["practice_electrokinetic_hacking_interface"] = "Contemplate your powers and improve your ability to psychically interface with computers.\n\nPower Difficulty: 4\n\nCurrent Power Level: <u_spell_level:electrokinetic_hacking_interface>",
    ["practice_electrokinetic_hacking_interface_knack"] = "Contemplate your powers and improve your ability to hack nearby devices with your powers.\n\nPower Difficulty: 2\n\nCurrent Power Level: <u_spell_level:electrokinetic_hacking_interface_knack>",
    ["practice_electrokinetic_kill_robot"] = "Contemplate your powers and improve your ability to overload robots and cyborgs.\n\nPower Difficulty: 7\n\nCurrent Power Level: <u_spell_level:electrokinetic_kill_robot>",
    ["practice_electrokinetic_lightning_aura"] = "Contemplate your powers and improve your ability to charge the nearby air to blast your enemies.\n\nPower Difficulty: 8\n\nCurrent Power Level: <u_spell_level:electrokinetic_lightning_aura>",
    ["practice_electrokinetic_lightning_blast"] = "Contemplate your powers and improve your ability to unleash enormous blasts of lightning.\n\nPower Difficulty: 9\n\nCurrent Power Level: <u_spell_level:electrokinetic_lightning_blast>",
    ["practice_electrokinetic_lightning_bolt"] = "Contemplate your powers and improve your ability to unleash blasts of lightning.\n\nPower Difficulty: 5\n\nCurrent Power Level: <u_spell_level:electrokinetic_lightning_bolt>",
