    ["practice_electrokinetic_paralysis"] = "Contemplate your powers and improve your ability to paralyze your targets.\n\nPower Difficulty: 4\n\nCurrent Power Level: <u_spell_level:electrokinetic_paralysis>",
    ["practice_electrokinetic_personal_battery"] = "Contemplate your powers and improve your ability to fuel personal electronic devices with your powers.\n\nPower Difficulty: 3\n\nCurrent Power Level: <u_spell_level:electrokinetic_personal_battery>",
    ["practice_electrokinetic_reduce_pain"] = "Contemplate your powers and improve your ability to reduce the effects of pain.\n\nPower Difficulty: 4\n\nCurrent Power Level: <u_spell_level:electrokinetic_reduce_pain>",
