    ["practice_electrokinetic_robot_interface"] = "Contemplate your powers and improve your ability to psychically hack into nearby robots.\n\nPower Difficulty: 8\n\nCurrent Power Level: <u_spell_level:electrokinetic_robot_interface>",
    ["practice_electrokinetic_see_electric"] = "Contemplate your powers and improve your ability to detect electrical creatures or robots.\n\nPower Difficulty: 1\n\nCurrent Power Level: <u_spell_level:electrokinetic_see_electric>",
    ["practice_electrokinetic_see_electric_knack"] = "Contemplate your powers and improve your ability to detect electrical creatures or robots.\n\nPower Difficulty: 1\n\nCurrent Power Level: <u_spell_level:electrokinetic_see_electric_knack>",
    ["practice_electrokinetic_speed_boost"] = "Contemplate your powers and improve your ability to increase your or an ally's speed.\n\nPower Difficulty: 6\n\nCurrent Power Level: <u_spell_level:electrokinetic_speed_boost>",
    ["practice_electrokinetic_zap_enemies"] = "Contemplate your powers and improve your ability to electrocute those who attack you.\n\nPower Difficulty: 2\n\nCurrent Power Level: <u_spell_level:electrokinetic_zap_enemies>",
    ["practice_learn_psionic_combat"] = "Study and attempt to internalize the practices in the VERDANT HAND Combat Protocol training manual.  There's a lot in there; it may take you more than one attempt to understand it.",
    ["practice_learn_psionic_mutation_control_power"] = "Study and attempt to internalize the practices in the EMERALD VANGUARD progress report.  This seems extremely complex and demanding; it may take you more than one attempt to understand it.",
    ["practice_learn_psionic_teleportation_warp_combat"] = "Study and attempt to internalize the practices in the Proposal: TURQUOISE KEYSTONE document.  This seems extremely complex and demanding; it may take you more than one attempt to understand it.",
    ["practice_photokinetic_camouflage"] = "Contemplate your powers and improve your ability to hide your presence from distant observers.\n\nPower Difficulty: 3\n\nCurrent Power Level: <u_spell_level:photokinetic_camouflage>",
    ["practice_photokinetic_camouflage_knack"] = "Contemplate your powers and improve your ability to hide your presence from distant observers.\n\nPower Difficulty: 2\n\nCurrent Power Level: <u_spell_level:photokinetic_camouflage_knack>",
    ["practice_photokinetic_create_light"] = "Contemplate your powers and improve your ability to create light at a distance.\n\nPower Difficulty: 2\n\nCurrent Power Level: <u_spell_level:photokinetic_create_light>",
